@app.route('/api/inventory/search', methods=['GET'])
def search_inventory():
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')

    # Input validation for price range
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price range'}), 400

    if not category:
        return jsonify({'error': 'Category required'}), 400

    # Build query with category filter
    query = f"SELECT id, name, category, price, stock FROM products WHERE category = '{category}' AND price BETWEEN {min_p} AND {max_p}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/inventory/item/<int:item_id>', methods=['GET'])
def get_item(item_id):
    db = get_db()
    result = db.execute('SELECT id, name, category, price, stock FROM products WHERE id = ?', (item_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/inventory/restock', methods=['POST'])
def restock():
    data = request.get_json()
    if not data or 'item_id' not in data or 'quantity' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    db = get_db()
    db.execute('UPDATE products SET stock = stock + ? WHERE id = ?',
               (int(data['quantity']), int(data['item_id'])))
    db.commit()
    return jsonify({'status': 'restocked'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
